import { render, screen, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router-dom';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { getInvitationHandoff, listInvitationHandoffs } from '@/api/interviewInvitations';
import { reportMockClientActionUiResult } from '@/api/clientActions';
import { handoff } from '@/test/invitationFixtures';
import { InterviewHubPage } from './InterviewHubPage';
vi.mock('@/api/interviewInvitations', () => ({ getInvitationHandoff: vi.fn(), listInvitationHandoffs: vi.fn(), confirmInvitation: vi.fn() }));
vi.mock('@/api/clientActions', () => ({ reportMockClientActionUiResult: vi.fn() }));
function mount() {
  render(<QueryClientProvider client={new QueryClient({ defaultOptions: { queries: { retry: false } } })}>
    <MemoryRouter initialEntries={[{ pathname: '/interviews', state: { mockClientAction: {
      action: 'interview.preparation.open', action_id: 'action-1', payload: { kind: 'interview_preparation_open',
        interview_id: 'interview-1', opportunity_id: 'job-1', expected_interview_version: 1,
        expected_opportunity_version: 2, source_operation_id: 'operation-1', preferred_surface: 'interviews' } } } }]}>
      <InterviewHubPage />
    </MemoryRouter></QueryClientProvider>);
}
describe('verified preparation handoff', () => {
  beforeEach(() => { vi.clearAllMocks(); vi.mocked(listInvitationHandoffs).mockResolvedValue([]); vi.mocked(getInvitationHandoff).mockResolvedValue(handoff); });
  it('acknowledges only after reading the exact owned versions and operation receipt', async () => {
    mount(); expect(await screen.findByText('测试公司 · 测试工程师')).toBeInTheDocument();
    await waitFor(() => expect(reportMockClientActionUiResult).toHaveBeenCalledWith('action-1', { outcome: 'acknowledged' }));
    expect(reportMockClientActionUiResult).toHaveBeenCalledTimes(1);
  });
  it.each(['stale', 'unknown', 'different-operation', 'forbidden'])('refuses %s handoff without fabricating success', async (kind) => {
    if (kind === 'forbidden') vi.mocked(getInvitationHandoff).mockRejectedValue(new Error('404'));
    else vi.mocked(getInvitationHandoff).mockResolvedValue({ ...handoff,
      interview: kind === 'stale' ? { ...handoff.interview, version: 2 } : handoff.interview,
      verification: { ...handoff.verification, conclusion: kind === 'unknown' ? 'unknown' : 'verified',
        operation_id: kind === 'different-operation' ? 'other-operation' : 'operation-1' } });
    mount(); await waitFor(() => expect(reportMockClientActionUiResult).toHaveBeenCalledWith('action-1', expect.objectContaining({ outcome: 'failed' })));
    expect(reportMockClientActionUiResult).not.toHaveBeenCalledWith('action-1', { outcome: 'acknowledged' });
  });
});

import { useEffect, useRef } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Link, useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { getInvitationHandoff, listInvitationHandoffs, type InvitationHandoff } from '@/api/interviewInvitations';
import { reportMockClientActionUiResult } from '@/api/clientActions';
import type { MockRouteActionState } from '@/types/clientAction';
import { ManualInvitationForm } from './ManualInvitationForm';

export function InterviewHubPage() {
  const queryClient = useQueryClient();
  const navigate = useNavigate();
  const location = useLocation();
  const [params] = useSearchParams();
  const action = (location.state as MockRouteActionState | null)?.mockClientAction;
  const payload = action?.action === 'interview.preparation.open'
    && action.payload.kind === 'interview_preparation_open' ? action.payload : null;
  const id = payload?.interview_id ?? params.get('interview');
  const handoff = useQuery({ queryKey: ['interview-handoff', id], queryFn: () => getInvitationHandoff(id!),
    enabled: !!id, retry: false, staleTime: 0 });
  const list = useQuery({ queryKey: ['interview-invitations'], queryFn: listInvitationHandoffs, retry: false });
  const acknowledged = useRef(new Set<string>());
  const matches = !!payload && !!handoff.data
    && handoff.data.interview.id === payload.interview_id
    && handoff.data.opportunity.id === payload.opportunity_id
    && handoff.data.interview.version === payload.expected_interview_version
    && handoff.data.opportunity.version === payload.expected_opportunity_version
    && handoff.data.verification.operation_id === payload.source_operation_id
    && ['verified', 'reconciled'].includes(handoff.data.verification.conclusion);
  useEffect(() => {
    if (!action || !payload || acknowledged.current.has(action.action_id) || handoff.isFetching) return;
    if (!handoff.isSuccess && !handoff.isError) return;
    acknowledged.current.add(action.action_id);
    reportMockClientActionUiResult(action.action_id, matches ? { outcome: 'acknowledged' }
      : { outcome: 'failed', reason: '面试交接已变化、不可用或尚未核实，请重新获取当前状态' });
    navigate(`/interviews?interview=${encodeURIComponent(payload.interview_id)}`, { replace: true, state: null });
  }, [action, payload, matches, handoff.isSuccess, handoff.isError, handoff.isFetching, navigate]);
  return <div className="mx-auto max-w-5xl space-y-6 p-6">
    <header><h1 className="text-2xl font-semibold">面试准备</h1><p>面试安排来自已确认事实；准备、模拟和复盘共用相关资料。</p></header>
    {id && <section aria-label="当前面试交接">
      {handoff.isPending || handoff.isFetching ? <p role="status">正在核实面试安排…</p>
        : handoff.isError ? <p role="alert">当前面试不可用或无权读取，请刷新后重试。</p>
        : handoff.data && (!payload || matches) ? <InterviewSummary row={handoff.data} />
          : <p role="alert">交接版本已发生变化，没有执行原页面动作。</p>}
    </section>}
    <ManualInvitationForm onConfirmed={(result) => {
      void queryClient.invalidateQueries();
      navigate(`/interviews?interview=${encodeURIComponent(result.interview.id)}`);
    }} />
    <section aria-label="已确认的面试"><h2 className="text-lg font-semibold">已确认的面试</h2>
      {list.isPending ? <p role="status">正在读取…</p> : list.isError ? <p role="alert">无法读取面试列表，不代表没有安排。</p>
        : !list.data?.length ? <p>还没有已确认的面试邀请。</p>
          : <div className="grid gap-4">{list.data.map((row) => <InterviewSummary key={row.interview.id} row={row} />)}</div>}
    </section>
  </div>;
}
function InterviewSummary({ row }: { row: InvitationHandoff }) {
  return <article className="space-y-2 rounded-xl border bg-white p-4">
    <h3 className="font-semibold">{row.company_name} · {row.job_title}</h3>
    <p>{row.original_time_text} · {row.source_timezone}</p>
    <p className="text-sm">{row.stage_label ?? '面试'} · 状态：{row.verification.conclusion === 'verified' ? '已核实' : row.verification.conclusion}</p>
    <div className="flex flex-wrap gap-4 text-sm">
      <Link to={`/career-process?opportunity=${encodeURIComponent(row.opportunity.id)}`}>查看机会与资料</Link>
      <Link to={`/general-chat?object_kind=interview_record&object_id=${encodeURIComponent(row.interview.id)}`}>与 Copilot 准备这场面试</Link>
      <Link to="/mock">选择资料并模拟</Link>
    </div>
  </article>;
}

import type { InvitationFacts } from '@/api/interviewInvitations';

export type InvitationDraft = Record<keyof InvitationFacts, string>;
const fields: Array<[keyof InvitationFacts, string, number, boolean]> = [
  ['company_name', '公司', 200, true], ['job_title', '岗位', 300, true],
  ['scheduled_start_at', '开始时间（含时区）', 40, true],
  ['source_timezone', '时间所属时区', 80, true],
  ['original_time_text', '原始时间描述', 300, true],
  ['scheduled_end_at', '结束时间（含时区，可选）', 40, false],
  ['stage_label', '面试阶段', 200, false], ['location', '面试地点', 500, false],
  ['meeting_url', '会议链接', 4000, false], ['contact_name', '联系人', 200, false],
  ['contact_email', '联系邮箱', 320, false],
];
export function invitationDraft(facts: Partial<InvitationFacts> = {}): InvitationDraft {
  return Object.fromEntries(fields.map(([key]) => [key, facts[key] ?? (
    key === 'source_timezone' ? Intl.DateTimeFormat().resolvedOptions().timeZone : ''
  )])) as InvitationDraft;
}
export function checkedFacts(draft: InvitationDraft): InvitationFacts {
  for (const [key, label, max, required] of fields) {
    if ((required && !draft[key].trim()) || draft[key].trim().length > max) throw new Error(`请核对${label}`);
  }
  const aware = (value: string) => /(?:Z|[+-]\d{2}:\d{2})$/i.test(value) && Number.isFinite(Date.parse(value));
  if (!aware(draft.scheduled_start_at) || (draft.scheduled_end_at && !aware(draft.scheduled_end_at))) {
    throw new Error('请提供明确带时区的日期时间，例如 2026-10-01T14:00:00+08:00');
  }
  if (draft.scheduled_end_at && Date.parse(draft.scheduled_end_at) <= Date.parse(draft.scheduled_start_at)) {
    throw new Error('结束时间必须晚于开始时间');
  }
  return Object.fromEntries(fields.map(([key, , , required]) => [key, draft[key].trim() || (required ? '' : null)])) as unknown as InvitationFacts;
}
export function InvitationFields({ value, onChange, disabled = false }: {
  value: InvitationDraft; onChange: (draft: InvitationDraft) => void; disabled?: boolean;
}) {
  return <fieldset disabled={disabled} className="grid gap-3 md:grid-cols-2">
    <legend className="sr-only">面试邀请事实</legend>
    {fields.map(([key, label, max, required]) => <label key={key} className="grid gap-1 text-sm">
      {label}<input className="rounded-lg border border-stone-300 bg-white p-2" value={value[key]}
        required={required} maxLength={max} onChange={(event) => onChange({ ...value, [key]: event.target.value })}
        placeholder={key === 'scheduled_start_at' ? '2026-10-01T14:00:00+08:00' : undefined} />
    </label>)}
  </fieldset>;
}
